import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Assets — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Assets — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/assets"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Assets — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/assets"}]]},"headers":[],"relativePath":"user-guide/assets.md","filePath":"user-guide/assets.md","lastUpdated":1792365712000}'),n={name:"user-guide/assets.md"};function r(i,e,d,l,c,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="assets-—-user-guide" tabindex="-1">Assets — User Guide <a class="header-anchor" href="#assets-—-user-guide" aria-label="Permalink to &quot;Assets — User Guide&quot;">​</a></h1><h2 id="who-can-use-assets" tabindex="-1">Who can use Assets <a class="header-anchor" href="#who-can-use-assets" aria-label="Permalink to &quot;Who can use Assets&quot;">​</a></h2><p>Your workspace must have the <strong>Assets</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>depreciate</code> as needed).</p><p>Without <strong>assign</strong>, you only see assets assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Assets</strong> from the sidebar (Operations area).</p><ul><li>Search by name, number, serial number, manufacturer, model, or location</li><li>Filter by status, category, and assignee, or toggle <strong>My Assets</strong></li><li>KPI cards summarize total, my assets, unassigned, and counts by status</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted asset from the row menu</li><li><strong>Delete permanently</strong> requires <code>assets.force.delete</code> (same posture as Vendors — not on default role maps)</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New asset</strong> (shortcut: <code>n</code> when the list is focused and you have create permission)</li><li>Enter name (required). Optionally set status, category, manufacturer, model, serial number, location, purchase details, useful life in months, salvage value, depreciation start, warranty end, assignee, and — when those modules are installed — vendor or employee custodian. When Vendors is installed, use <strong>New</strong> beside the vendor picker to create and select a vendor inline (<code>vendors.create</code>)</li><li>Save — EloSync assigns the next asset number (<code>AST-00001</code>, …)</li></ol><p>Edit from the row menu or the asset page. Focus search with <code>Ctrl/⌘+F</code>.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the workspace assignee from the asset page or the create/edit form.</p><p>Assignees may be any <strong>active</strong> (non-suspended) workspace user, including workspace owners and users flagged <strong>Exclude from lead assignment</strong> (that flag is Leads-only). Suspended users are omitted from the picker. Clear assignee with <strong>Unassigned</strong>.</p><h2 id="vendor-employee-links" tabindex="-1">Vendor &amp; employee links <a class="header-anchor" href="#vendor-employee-links" aria-label="Permalink to &quot;Vendor &amp; employee links&quot;">​</a></h2><ul><li><strong>Vendor</strong> appears only when the Vendors module is installed</li><li><strong>Employee</strong> (custodian) appears only when the Employees module is installed</li></ul><p>These are optional context links — Assets works without either module.</p><h2 id="depreciation" tabindex="-1">Depreciation <a class="header-anchor" href="#depreciation" aria-label="Permalink to &quot;Depreciation&quot;">​</a></h2><p>When <strong>Accounting</strong> is installed and your role has <code>assets.depreciate</code>:</p><ul><li><strong>Post depreciation</strong> on the asset page posts one month for that asset</li><li><strong>Post depreciation</strong> on the Assets list posts that month for every eligible asset</li><li>The first post capitalizes purchase cost: debit Fixed Assets <code>1500</code>, credit Owner Equity <code>3000</code></li><li>Each month debits Depreciation Expense <code>6500</code> and credits Accumulated Depreciation <code>1550</code></li><li>Straight-line amount is <code>(purchase cost − salvage) / useful life months</code>. The last month takes any rounding remainder</li><li>Retired and disposed assets are skipped. A month already posted is rejected on one asset and skipped in the batch</li><li>An asset currency other than the workspace currency is not posted</li><li>Without Accounting, the depreciation fields still save and no journal is written</li></ul><p>The asset page shows accumulated depreciation, book value, the capitalization journal, and each posted month.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the asset</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Active</td><td>In normal use</td></tr><tr><td>In repair</td><td>Temporarily unavailable</td></tr><tr><td>Retired</td><td>No longer in active use</td></tr><tr><td>Disposed</td><td>Written off / removed</td></tr></tbody></table>',24)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
